namespace sv_931ac04e14794c22a56483604d062ca1.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

public record ThemeInfo(ThemeMode Mode, string AccentColor);

using Microsoft.AspNetCore.Components;

namespace sv_931ac04e14794c22a56483604d062ca1.Services;

/// <summary>
/// Scoped service (per circuit) that owns the current theme state and
/// pushes updates to all subscribers via CascadingValueSource.
/// </summary>
public class ThemeService : IDisposable
{
    private readonly CascadingValueSource<ThemeInfo> _source;

    public ThemeService(CascadingValueSource<ThemeInfo> source)
    {
        _source = source;
    }

    public ThemeInfo Current { get; private set; } = new(ThemeMode.Light, "#0d6efd");

    public event Action? OnChange;

    public async Task SetThemeModeAsync(ThemeMode mode)
    {
        Current = Current with { Mode = mode };
        await NotifyAsync();
    }

    public async Task SetAccentColorAsync(string color)
    {
        Current = Current with { AccentColor = color };
        await NotifyAsync();
    }

    public async Task SetThemeAsync(ThemeMode mode, string accentColor)
    {
        Current = new ThemeInfo(mode, accentColor);
        await NotifyAsync();
    }

    private async Task NotifyAsync()
    {
        // Push new value to all [CascadingParameter] subscribers (crosses render-mode boundaries)
        await _source.NotifyChangedAsync(Current);
        // Also fire event for components that subscribe via the service directly
        OnChange?.Invoke();
    }

    public void Dispose()
    {
        OnChange = null;
    }
}

