@* Theme indicator that lives in the static layout but reacts to theme changes
   via the scoped ThemeService event (not cascading, since this is static SSR). *@

@inject ThemeService ThemeService
@implements IDisposable

<span class="badge rounded-pill"
      style="background-color: @ThemeService.Current.AccentColor; color: white;">
    @ThemeService.Current.Mode
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        ThemeService.OnChange += _handler;
    }

    public void Dispose()
    {
        ThemeService.OnChange -= _handler;
    }
}

@page "/settings"
@rendermode InteractiveServer

@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 480px;">
    <h5>Theme</h5>
    <div class="btn-group mb-3" role="group">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            var isActive = mode == currentMode;
            <button type="button"
                    class="btn @(isActive ? "btn-primary" : "btn-outline-primary")"
                    @onclick="() => SetMode(mode)">
                @mode
            </button>
        }
    </div>

    <h5>Accent Color</h5>
    <input type="color" class="form-control form-control-color mb-3"
           value="@currentAccent"
           @onchange="OnAccentChanged" />

    <p>
        Current:
        <strong style="color: @currentAccent;">@currentMode</strong>
        / @currentAccent
    </p>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private ThemeMode currentMode;
    private string currentAccent = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentMode = Theme.Mode;
            currentAccent = Theme.AccentColor;
        }
    }

    private async Task SetMode(ThemeMode mode)
    {
        currentMode = mode;
        await ThemeService.SetThemeAsync(currentMode, currentAccent);
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        currentAccent = e.Value?.ToString() ?? currentAccent;
        await ThemeService.SetThemeAsync(currentMode, currentAccent);
    }
}

